import pandas as pd
import random
import re

def task_func(data_list, seed=None):
    if seed is not None:
        random.seed(seed)

    originals = []
    modified = []

    operations = ["remove", "replace", "shuffle", "randomize"]

    for s in data_list:
        if not isinstance(s, str):
            s = str(s)

        originals.append(s)
        substrings = s.split(",")

        op = random.choice(operations)

        if op == "remove":
            if len(substrings) > 1:
                remove_idx = random.randrange(len(substrings))
                substrings = substrings[:remove_idx] + substrings[remove_idx + 1 :]
            # If there is only one substring, do nothing.

        elif op == "replace":
            replace_idx = random.randrange(len(substrings))
            substrings[replace_idx] = "random_string"

        elif op == "shuffle":
            random.shuffle(substrings)

        elif op == "randomize":
            substrings = random.sample(substrings, k=len(substrings))

        modified.append(",".join(substrings))

    df = pd.DataFrame(
        {
            "Original String": originals,
            "Modified String": modified,
        }
    )
    return df
